<?php $id=get_the_ID();$p=wc_get_product($id);$data=null;foreach(bj_catalogue_data() as $item)if($item['id']===$id)$data=$item;if(!$data)return;$first=$data['sizes'][0]??null; ?>
<section class="mt-section bjx bjx-sec bj-product"><div class="container-xl">
<div class="bjx-crumb"><a href="<?php echo esc_url(bj_page_url('index')); ?>"><?php echo esc_html(bj_t('home')); ?></a> / <a href="<?php echo esc_url(bj_page_url('products')); ?>"><?php echo esc_html(bj_t('products')); ?></a> / <?php echo esc_html($data['title']); ?></div>
<div class="bjx-pp"><div class="pk"><img id="pp-img" src="<?php echo esc_url($first['image']??$data['image']); ?>" alt="<?php echo esc_attr($data['title']); ?>"></div>
<div><h1><?php echo esc_html($data['title']); ?></h1>
<?php if($first): ?><h3><?php echo esc_html(bj_t('select_size')); ?></h3><div class="bjx-sizes" data-product="<?php echo esc_attr($id); ?>" role="group" aria-label="<?php echo esc_attr(bj_t('select_size')); ?>"><?php foreach($data['sizes'] as $i=>$size): ?><button type="button" data-index="<?php echo esc_attr($i); ?>" aria-pressed="<?php echo $i===0?'true':'false'; ?>"><?php echo esc_html(bj_language()==='ar'?($size['size_ar']?:$size['size']):$size['size']); ?></button><?php endforeach; ?></div><?php endif; ?>
<table class="bjx-spec"><?php foreach($p->get_attributes() as $a):if($a->get_variation())continue;$name=wc_attribute_label($a->get_name());$value=$p->get_attribute($a->get_name());if(bj_language()==='ar')foreach((array)bj_field('attribute_labels_ar',$id) as $r)if($r['attribute_name']===$a->get_name()){$name=$r['attribute_label_ar'];$value=$r['attribute_value_ar'];} ?><tr><th><?php echo esc_html($name); ?></th><td><?php echo esc_html($value); ?></td></tr><?php endforeach; ?>
<?php if($first): ?><tr><th><?php echo esc_html(bj_t('size')); ?></th><td id="pp-s"></td></tr><tr><th><?php echo esc_html(bj_t('weight_range')); ?></th><td id="pp-w"></td></tr><tr><th><?php echo esc_html(bj_t('pack_counts')); ?></th><td id="pp-pk"></td></tr><?php endif; ?></table>
<?php $description=bj_language()==='ar'?bj_field('description_ar',$id):$p->get_description();echo wp_kses_post(wpautop($description)); ?>
<?php $benefits=bj_field('benefits',$id);if($benefits): ?><h3><?php echo esc_html(bj_t('benefits')); ?></h3><ul class="bjx-ben"><?php foreach($benefits as $r): ?><li><?php echo esc_html($r[bj_language()==='ar'?'benefit_ar':'benefit_en']); ?></li><?php endforeach; ?></ul><?php endif; ?>
<?php $retailers=do_shortcode('[babyjoy_retailers product="'.$id.'"]');if($retailers): ?><h3><?php echo esc_html(bj_t('where_to_buy')); ?></h3><?php echo $retailers;endif; ?>
<?php if($first): ?><p><a class="mt-btn" href="<?php echo esc_url(bj_page_url('index').'#size-guide'); ?>"><?php echo esc_html(bj_t('size_guide')); ?></a></p><?php endif; ?>
</div></div></div></section>
